package com.acme.orders.service; import com.acme.orders.dto.*; import com.acme.orders.entity.PurchaseOrder; import com.acme.orders.repository.OrderRepository; import java.math.BigDecimal; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.client.*;
@Service @Transactional public class OrderService {private final OrderRepository repo;private final RestClient catalog;public OrderService(OrderRepository repo,@Value("${catalog.url}") String url){this.repo=repo;this.catalog=RestClient.builder().baseUrl(url).build();}public OrderResponse create(CreateOrderRequest r){Product product;try{product=catalog.get().uri("/api/products/{sku}",r.sku()).retrieve().body(Product.class);}catch(RestClientResponseException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown or inactive SKU");}if(product==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown SKU");return OrderResponse.of(repo.save(new PurchaseOrder(r.customerEmail(),r.sku(),r.quantity(),product.price())));}public java.util.List<OrderResponse> all(){return repo.findAll().stream().map(OrderResponse::of).toList();}record Product(String sku,String name,BigDecimal price,boolean active){}}
